import{_ as o}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t,a as r,b as l,c as n,d as s,e as p}from"./chunks/M-S-SW-MB-I5.BZKmfHD5.js";import{_ as a}from"./chunks/ON.DXVlsWbj.js";import{_ as i}from"./chunks/OFF.BrU7kQE-.js";import{_ as d}from"./chunks/EN.P9aPnFBv.js";import{_ as c,o as m,c as u,a3 as h}from"./chunks/framework.g9mfNVRQ.js";const C=JSON.parse('{"title":"MiBand","description":"","frontmatter":{"source_hash":"47eb878cea","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/smartwatch/miband.md","filePath":"it/smartwatch/miband.md"}'),g={name:"it/smartwatch/miband.md"};function v(b,e,f,z,y,w){return m(),u("div",null,[...e[0]||(e[0]=[h('<div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Caratteristiche Collegamenti Smart Watch<br>   MiBand</p></div><p>La release ufficiale di xDrip supporta MiBand 2, 3, 4 e la trasmissione a <a href="https://bigdigital.home.blog/2022/06/16/watchdrip-a-new-application-for-xdrip-watch-integration" target="_blank" rel="noreferrer">WatchDrip+</a> per le altre smartband.</p><div class="info custom-block"><p class="custom-block-title">Prerequisito</p><p>Assicurati di avere le letture della glicemia in xDrip prima di provare a vederle sull&#39;orologio.<br> Se xDrip non riceve le letture sul telefono, non verranno mostrate sull&#39;orologio.</p></div><h2 id="install" tabindex="-1">Installazione <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Installazione {#install}&quot;">​</a></h2><h3 id="obtain-an-authentication-key" tabindex="-1">Ottenere una chiave di autenticazione <a class="header-anchor" href="#obtain-an-authentication-key" aria-label="Permalink to &quot;Ottenere una chiave di autenticazione {#obtain-an-authentication-key}&quot;">​</a></h3><h4 id="if-you-already-paired-your-watch-with-the-vendor-app" tabindex="-1">Se hai già associato l&#39;orologio all&#39;app del produttore <a class="header-anchor" href="#if-you-already-paired-your-watch-with-the-vendor-app" aria-label="Permalink to &quot;Se hai già associato l&#39;orologio all&#39;app del produttore {#if-you-already-paired-your-watch-with-the-vendor-app}&quot;">​</a></h4><ul><li><p>Dissocia l&#39;orologio.</p></li><li><p>Disinstalla MiFit o Zepp, o qualunque app tu abbia usato per collegare l&#39;orologio.</p></li><li><p><strong>Elimina i vecchi file della chiave</strong> (usa un file manager sul telefono) nella cartella <code>freemyband</code> della memoria del telefono.<br> Consigliato se non riesci a far collegare xDrip all&#39;orologio.<br><em>Nota: il nome qui sotto è un esempio</em></p></li></ul><img src="'+t+'" style="zoom:75%;"><h4 id="install-the-patched-app-matching-your-watch" tabindex="-1">Installa l&#39;app modificata adatta al tuo orologio <a class="header-anchor" href="#install-the-patched-app-matching-your-watch" aria-label="Permalink to &quot;Installa l&#39;app modificata adatta al tuo orologio {#install-the-patched-app-matching-your-watch}&quot;">​</a></h4><p>Vai su <a href="https://www.freemyband.com/" target="_blank" rel="noreferrer">https://www.freemyband.com/</a></p><p>Scarica e installa <a href="https://www.freemyband.com/2019/08/amazfit-gtr-auth-key.html" target="_blank" rel="noreferrer">Zepp</a> per gli orologi Amazfit.<br> (oppure)<br> Scarica e installa <a href="https://www.freemyband.com/2019/08/mi-band-4-auth-key.html" target="_blank" rel="noreferrer">MiFit</a> per le smartband Xiaomi.</p><p>Accedi con email e password. Crea un account se necessario.</p><p>Associa la smartband.</p><p>Attiva la visibilità dell&#39;orologio. Se non trovi questa opzione, verifica di aver impostato un&#39;età di almeno 18 anni.</p><p>Controlla che sia stato creato un file della chiave nella cartella <code>freemyband</code> della memoria del telefono.</p><p>Puoi disinstallare l&#39;app modificata, ma non è obbligatorio. Se vuoi installare l&#39;app originale, accedi con lo stesso account email.</p><h2 id="not-using-watchdrip" tabindex="-1">Senza WatchDrip+ <a class="header-anchor" href="#not-using-watchdrip" aria-label="Permalink to &quot;Senza WatchDrip+ {#not-using-watchdrip}&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Solo MiBand 2, 3 e 4</p></div><h3 id="setup-xdrip" tabindex="-1">Configurare xDrip <a class="header-anchor" href="#setup-xdrip" aria-label="Permalink to &quot;Configurare xDrip {#setup-xdrip}&quot;">​</a></h3><p>Attiva la funzione MiBand. Tieni l&#39;orologio vicino al telefono finché non viene rilevato.</p><div class="admonition xdripitem"><p class="admonition-title">Usa MiBand <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><img src="'+r+'" style="zoom:80%;"><p>L&#39;indirizzo MAC dovrebbe compilarsi automaticamente.</p><div class="admonition xdripitem"><p class="admonition-title">Indirizzo MAC (FF:EE:DD:CC:BB:AA)</p><p> Lascia vuoto per la ricerca automatica</p></div><p><strong>Se non succede</strong> (caso anomalo)<strong>:</strong><br> Elimina i file nella cartella <code>freemyband</code>.<br> Apri l&#39;app modificata dell&#39;orologio.<br> Riprova: disattiva e riattiva la funzione MiBand.</p><p>Puoi anche provare a inserire manualmente l&#39;indirizzo MAC dell&#39;orologio. Lo trovi nel nome del file nella cartella <code>freemyband</code>.<br> Ad esempio, se il nome è <code>mibandFFEEDDCCBBAA.txt</code>, l&#39;indirizzo MAC corrispondente sarà <code>FF:EE:DD:CC:BB:AA</code>.</p><img src="'+l+'" style="zoom:75%;"><p>Tieni d&#39;occhio i messaggi a comparsa: durante l&#39;autenticazione dello smartwatch dovresti vedere quanto segue:</p><img src="'+n+'" style="zoom:75%;"><p>Se l&#39;autorizzazione non riesce, elimina i file nella cartella <code>freemyband</code> e apri l&#39;app modificata per rigenerarli.</p><img src="'+s+'" style="zoom:75%;"><p>Se xDrip non riesce a ottenere automaticamente la chiave di autenticazione, puoi provare a inserirla manualmente. La trovi aprendo il file in modifica.</p><img src="'+p+'" style="zoom:75%;"><p>Prima di inserire la chiave manualmente, assicurati che l&#39;orologio sia collegato e corrisponda all&#39;indirizzo MAC.</p><div class="admonition xdripitem"><p class="admonition-title">Chiave di autenticazione</p><p> Imposta la chiave di autenticazione per MiBand4 (Per ottenere la chiave di autenticazione, segui le istruzioni su <a href="https://www.freemyband.com/2019/08/mi-band-4-auth-key.html" target="_blank" rel="noreferrer">https://www.freemyband.com</a>)</p></div><p>Una volta collegato e autenticato l&#39;orologio, attiva Invia Letture. Aspetta il valore successivo in xDrip: il quadrante dovrebbe aggiornarsi.</p><div class="admonition xdripitem"><p class="admonition-title">Invia Letture <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Data dell&#39;orologio aggiustata per visualizzare i valori di glicemia. Meglio mmol/l - consultare la documentazione</p></div><p>Per forzare l&#39;aggiornamento dell&#39;orologio, puoi inviare una lettura manualmente. Osserva bene i messaggi a comparsa.</p><div class="admonition xdripitem"><p class="admonition-title">Aggiorna la glicemia manualmente</p></div><p>Se hai problemi a visualizzare il grafico, prova a disattivare i valori MTU elevati.</p><div class="admonition xdripitem"><p class="admonition-title">Disable hight MTU values <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><h3 id="features" tabindex="-1">Funzioni <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Funzioni {#features}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Usa MiBand <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Sincronizza i dati con fitness band MiBand</p></div><p>Puoi attivare e disattivare l&#39;integrazione MiBand con l&#39;interruttore principale. Durante la risoluzione dei problemi non esitare a spegnerlo e riaccenderlo per riavviarla.</p><div class="admonition xdripitem"><p class="admonition-title">Indirizzo MAC</p><p> Lascia vuoto per la ricerca automatica</p></div><p>L&#39;indirizzo MAC dell&#39;orologio dovrebbe essere rilevato automaticamente quando il campo è lasciato vuoto. Puoi modificarlo manualmente e scrivere i 6 valori esadecimali a due cifre del tuo orologio, separati da due punti.</p><div class="admonition xdripitem"><p class="admonition-title">Chiave di autenticazione</p><p> Imposta la chiave di autenticazione per MiBand4 (Per ottenere la chiave di autenticazione, segui le istruzioni su <a href="https://www.freemyband.com/2019/08/mi-band-4-auth-key.html" target="_blank" rel="noreferrer">https://www.freemyband.com</a>)</p></div><p>Quando viene trovato un indirizzo MAC valido, vedrai anche il campo della chiave. Se non viene compilato automaticamente, puoi inserire manualmente la chiave di autenticazione di 32 caratteri.</p><div class="admonition xdripitem"><p class="admonition-title">Invia Letture <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Data dell&#39;orologio aggiustata per visualizzare i valori di glicemia. Meglio mmol/l - consultare la documentazione</p></div><p>Devi attivare questa opzione perché le letture vengano inviate all&#39;orologio.</p><div class="admonition xdripitem"><p class="admonition-title">Vibra alle letture <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Invia Allarmi <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Invia le notifiche per gli allarmi di glicemia alla Band</p></div><div class="admonition xdripitem"><p class="admonition-title">Invia Chiamate <span class="symbol"><img src="'+d+'" style="zoom:75%;"></span></p><p> Invia notifiche di chiamata alla band (Android 6+)</p></div><p>Puoi attivare varie opzioni per far vibrare l&#39;orologio a ogni lettura, ricevere gli allarmi o ricevere le notifiche come chiamate telefoniche.</p><div class="admonition xdripitem"><p class="admonition-title">Aggiorna la glicemia manualmente</p></div><p>Puoi forzare l&#39;aggiornamento del quadrante con Aggiorna la glicemia manualmente.</p><div class="admonition xdripitem"><p class="admonition-title">Schermate MiBand / Caratteristiche</p></div><p>In questo menu sono disponibili altre personalizzazioni.</p><div class="admonition xdripitem"><p class="admonition-title">Allow to use custom watchface <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><p>Con queste funzioni puoi creare il tuo quadrante e modificare l&#39;immagine di sfondo.<br> Lasciale disattivate a meno che tu non abbia preparato correttamente i file necessari nella cartella xdrip del telefono.</p><p>Per consigli ed esempi guarda <a href="https://github.com/twinko" target="_blank" rel="noreferrer">qui</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Disable hight MTU values <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><p>Disable high MTU values (disattiva i valori MTU elevati) può essere usato in caso di problemi di visualizzazione del quadrante.</p><h2 id="using-watchdrip" tabindex="-1">Con WatchDrip+ <a class="header-anchor" href="#using-watchdrip" aria-label="Permalink to &quot;Con WatchDrip+ {#using-watchdrip}&quot;">​</a></h2><h3 id="install-watchdrip" tabindex="-1">Installa <a href="https://bigdigital.home.blog/2022/06/16/watchdrip-a-new-application-for-xdrip-watch-integration/" target="_blank" rel="noreferrer">WatchDrip+</a> <a class="header-anchor" href="#install-watchdrip" aria-label="Permalink to &quot;Installa [WatchDrip+](https://bigdigital.home.blog/2022/06/16/watchdrip-a-new-application-for-xdrip-watch-integration/) {#install-watchdrip}&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Disattiva MiBand in xDrip se usi WatchDrip+</p><div class="admonition xdripitem"><p class="admonition-title">Usa MiBand <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div></div><h3 id="setup-xdrip-1" tabindex="-1">Configurare xDrip <a class="header-anchor" href="#setup-xdrip-1" aria-label="Permalink to &quot;Configurare xDrip {#setup-xdrip-1}&quot;">​</a></h3><p>Attiva Servizio di Trasmissione API in Impostazioni -&gt; Impostazioni Inter-app</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_open_in_app_grey600_48dp.png" style="width:5%;"> Impostazioni Inter-app</p></div><div class="admonition xdripitem"><p class="admonition-title">Servizio di Trasmissione API <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Abilita la comunicazione tra xDrip e applicazioni terze parti utilizzando la nuova API</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',72)])])}const M=c(g,[["render",v]]);export{C as __pageData,M as default};
